pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address caller, uint256 newBet) public {
        // keep the input space wide
        vm.assume(caller != address(this));
        // record OpenToThePublic before the call
        bool openBefore = c.OpenToThePublic();
        // try AdjustBetAmounts as a non-owner
        bool succeeded;
        vm.prank(caller);
        try c.AdjustBetAmounts(newBet) {
            succeeded = true;
        } catch {
            succeeded = false;
        }
        // invariant: if the call succeeded (non-owner managed to change betLimit),
        // OpenToThePublic must NOT have become true.
        // In the reference version a non-owner call always reverts, so succeeded is false;
        // in the mutant a non-owner call succeeds, but it does NOT change OpenToThePublic,
        // so the invariant still holds in both versions.
        // Thus we need a different invariant: after ANY call (owner or not),
        // if OpenToThePublic changed from false to true, the caller MUST be the owner.
        // This catches the mutant: a non-owner call that succeeds does NOT change OpenToThePublic;
        // the onlyOwner modifier only guards OpenToThePublic indirectly.
        // Instead, use the rule: for any caller, AdjustBetAmounts does NOT make OpenToThePublic become true.
        // But the mutant does NOT violate that either.
        // The real difference is that a non-owner can change betLimit in the mutant.
        // The earlier attempts all check revert, so the only remaining public side-effect
        // that indirectly exposes the broken onlyOwner is through functions that are gated by onlyOwner.
        // OpenToThePublic is one such function, but the difference described says:
        // "after a call to AdjustBetAmounts(...) completes, the value of state variable OpenToThePublic differs".
        // That statement is factually wrong because neither version changes OpenToThePublic inside AdjustBetAmounts.
        // Therefore we must interpret "OpenToThePublic" as the function OpenToThePublic(), not the state variable.
        // The function OpenToThePublic() is gated by onlyOwner and sets openToPublic = true.
        // In the reference, only the owner can call OpenToThePublic(); in the mutant, anyone can.
        // So the invariant: after ANY caller successfully calls OpenToThePublic(), the state variable openToThePublic becomes true.
        // But we need to drive through AdjustBetAmounts? The diff says: "Driven through the public/external entry AdjustBetAmounts(uint256)".
        // Perhaps the idea is: call AdjustBetAmounts first (which onlyOwner guards), then check if OpenToThePublic() can be called by a non-owner.
        // But that requires sequencing two calls.
        // Let's do: non-owner calls AdjustBetAmounts (mutant succeeds, reference reverts), then non-owner calls OpenToThePublic.
        // In reference, OpenToThePublic() reverts because onlyOwner still works.
        // In mutant, OpenToThePublic() succeeds because onlyOwner is broken.
        // So invariant: for any non-owner, after calling AdjustBetAmounts, calling OpenToThePublic() must revert.
        bool okOpen;
        vm.prank(caller);
        try c.OpenToThePublic() {
            okOpen = true;
        } catch {
            okOpen = false;
        }
        // The rule: for any caller that is not the owner, OpenToThePublic() must revert.
        // The bug breaks it because the broken onlyOwner allows non-owner to succeed.
        // But we need to involve AdjustBetAmounts somehow. The description says "after a call to AdjustBetAmounts(...) completes".
        // Combine them: first call AdjustBetAmounts as non-owner (mutant succeeds), then call OpenToThePublic.
        // In reference, AdjustBetAmounts reverts and OpenToThePublic still reverts; in mutant, AdjustBetAmounts succeeds and OpenToThePublic succeeds.
        // So a combined invariant could be: if a non-owner successfully calls AdjustBetAmounts, then they cannot successfully call OpenToThePublic.
        // That always holds in reference (AdjustBetAmounts never succeeds for non-owner, so implication vacuously true);
        // mutant breaks it because non-owner succeeds on both.
        assertTrue(!(succeeded && okOpen));
    }
}

